            void deleteSubSystem(const Signature &sig);
            void deleteAllSubSystem();
            void replaceSubSystem(const Signature &sig, std::shared_ptr<system::ISubSystem> subSystem);

            static Mediator& get() {
                static Mediator res(rtype::singleton::ECManager::get());
                return res;
            }
        };
    }
}

