        return _sysListGame;
    }
    // else menu
    //if  (_currentScene == rtype::client::scenes::MENU) {
        // med.addSubSystem(Signature(rtype::idBitset::idQueueMessageSendClient), _subSysList[rtype::client::NetworkWriterIndex::TCP]);
    this->applySceneEntities();
    return _sysListMenu;
    // }
}

