{
    std::cout << "[CLIENT]: [SYSTEM]: [INTERPRETNETWORKCLIENT]: handleEndMssg" << std::endl;
    if (!msg.size())
        return;
    rtype::entity::ComponentManager &ecMan = rtype::singleton::ECManager::get();
