#ifndef COMMONCOMPONENTIMANAGER_HPP_
#define COMMONCOMPONENTIMANAGER_HPP_

#include <string>

using Entity = std::string;

namespace rtype {
    namespace component {

        template<typename T>
        class IManager
        {
            public:
                virtual ~IManager() = default;

